import{c as t,Q as l,j as a,m as d}from"./chunks/framework.7r1mYKiJ.js";const y=JSON.parse('{"title":"Placeholders & Variables","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/placeholders.md","filePath":"configuration/placeholders.md"}'),r={name:"configuration/placeholders.md"};function o(s,e,i,c,n,h){return l(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="placeholders-variables" tabindex="-1">Placeholders &amp; Variables <a class="header-anchor" href="#placeholders-variables" aria-label="Permalink to &quot;Placeholders &amp; Variables&quot;">​</a></h1><p>AetherUHC integrates natively with <strong>PlaceholderAPI</strong> (PAPI) to allow you to display UHC statistics, states, and timers anywhere on your server—from holograms to external scoreboard plugins or chat prefixes!</p><p>To use these placeholders, ensure you have PlaceholderAPI installed on your server.</p><h2 id="global-placeholders" tabindex="-1">Global Placeholders <a class="header-anchor" href="#global-placeholders" aria-label="Permalink to &quot;Global Placeholders&quot;">​</a></h2><p>These placeholders return information about the current state of the UHC match and are the same for all players.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Placeholder</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example Output</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%aetheruhc_state%</code></td><td style="text-align:left;">The current game state.</td><td style="text-align:left;"><code>LOBBY</code>, <code>SCATTERING</code>, <code>PLAYING</code>, <code>DEATHMATCH</code>, <code>ENDED</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_timer%</code></td><td style="text-align:left;">The formatted countdown or elapsed match time.</td><td style="text-align:left;"><code>45:00</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_alive_players%</code></td><td style="text-align:left;">The number of players currently alive.</td><td style="text-align:left;"><code>24</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_spectators%</code></td><td style="text-align:left;">The number of players currently spectating.</td><td style="text-align:left;"><code>5</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_border%</code></td><td style="text-align:left;">The current size of the world border.</td><td style="text-align:left;"><code>1000</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_scenarios%</code></td><td style="text-align:left;">A comma-separated list of active scenarios.</td><td style="text-align:left;"><code>CutClean, Timebomb</code></td></tr></tbody></table><h2 id="player-placeholders" tabindex="-1">Player Placeholders <a class="header-anchor" href="#player-placeholders" aria-label="Permalink to &quot;Player Placeholders&quot;">​</a></h2><p>These placeholders return statistics specific to the player viewing them.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Placeholder</th><th style="text-align:left;">Description</th><th style="text-align:left;">Example Output</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%aetheruhc_kills%</code></td><td style="text-align:left;">The player&#39;s kill count in the current match.</td><td style="text-align:left;"><code>3</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_team_kills%</code></td><td style="text-align:left;">The combined kill count of the player&#39;s team.</td><td style="text-align:left;"><code>5</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_alltime_kills%</code></td><td style="text-align:left;">The player&#39;s all-time total kill count.</td><td style="text-align:left;"><code>142</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_alltime_wins%</code></td><td style="text-align:left;">The player&#39;s all-time total wins.</td><td style="text-align:left;"><code>12</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_alltime_deaths%</code></td><td style="text-align:left;">The player&#39;s all-time total deaths.</td><td style="text-align:left;"><code>89</code></td></tr><tr><td style="text-align:left;"><code>%aetheruhc_alltime_kdr%</code></td><td style="text-align:left;">The player&#39;s all-time Kill/Death Ratio.</td><td style="text-align:left;"><code>1.59</code></td></tr></tbody></table><h2 id="internal-variables" tabindex="-1">Internal Variables <a class="header-anchor" href="#internal-variables" aria-label="Permalink to &quot;Internal Variables&quot;">​</a></h2><p>Inside of <code>Language.java</code> and internal plugin messages, AetherUHC uses its own fast parsing system instead of PlaceholderAPI. You will often see variables wrapped in <code>&lt; &gt;</code>.</p><ul><li><code>&lt;player&gt;</code>: The relevant player&#39;s name.</li><li><code>&lt;killer&gt;</code>: The name of the player who killed them.</li><li><code>&lt;time&gt;</code>: A formatted time string.</li></ul>',12)])])}const p=t(r,[["render",o]]);export{y as __pageData,p as default};
